11: static int skip_chunk(const char *buf, int len, int *pl, int *dl) {
12:   int i = 0, n = 0;
13:   if (len < 3) return 0;
14:   while (i < len && is_hex_digit(buf[i])) i++;
15:   if (i == 0) return -1;                     // Error, no length specified
16:   if (i > (int) sizeof(int) * 2) return -1;  // Chunk length is too big
17:   if (len < i + 1 || buf[i] != '\r' || buf[i + 1] != '\n') return -1;  // Error
18:   if (mg_str_to_num(mg_str_n(buf, (size_t) i), 16, &n, sizeof(int)) == false)
19:     return -1;                    // Decode chunk length, overflow
20:   if (n < 0) return -1;           // Error. TODO(): some checks now redundant
21:   if (n > len - i - 4) return 0;  // Chunk not yet fully buffered
22:   if (buf[i + n + 2] != '\r' || buf[i + n + 3] != '\n') return -1;  // Error
23:   *pl = i + 2, *dl = n;
24:   return i + 2 + n + 2;
25: }
